(function(){"use strict";var uid=0;function flagFR(){return'<svg class="lang-flag" viewBox="0 0 30 20" aria-hidden="true" focusable="false" role="img"><rect width="30" height="20" fill="#002654"/><rect x="10" width="10" height="20" fill="#FFFFFF"/><rect x="20" width="10" height="20" fill="#ED2939"/></svg>'}function flagEN(){uid+=1;var s="tfhuk-"+uid+"-s",t="tfhuk-"+uid+"-t";return'<svg class="lang-flag" viewBox="0 0 60 30" aria-hidden="true" focusable="false" role="img"><defs><clipPath id="'+s+'"><path d="M0,0 v30 h60 v-30 z"/></clipPath><clipPath id="'+t+'"><path d="M30,15 h30 v15 z v15 h-30 z h-30 v-15 z v-15 h30 z"/></clipPath></defs><g clip-path="url(#'+s+')"><path d="M0,0 v30 h60 v-30 z" fill="#012169"/><path d="M0,0 L60,30 M60,0 L0,30" stroke="#FFFFFF" stroke-width="6"/><path d="M0,0 L60,30 M60,0 L0,30" clip-path="url(#'+t+')" stroke="#C8102E" stroke-width="4"/><path d="M30,0 v30 M0,15 h60" stroke="#FFFFFF" stroke-width="10"/><path d="M30,0 v30 M0,15 h60" stroke="#C8102E" stroke-width="6"/></g></svg>'}var LANGS=[{code:"fr",flag:flagFR,label:"Fran\xE7ais"},{code:"en",flag:flagEN,label:"English"}];function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}function buttonsHtml(){return LANGS.map(function(l){return'<button type="button" class="lang-btn" data-lang="'+l.code+'" aria-label="'+esc(l.label)+'" title="'+esc(l.label)+'"><span class="flag-wrap">'+l.flag()+"</span></button>"}).join("")}function sync(current){document.querySelectorAll(".lang-btn[data-lang]").forEach(function(btn){var active=btn.getAttribute("data-lang")===current;btn.classList.toggle("active",active),btn.setAttribute("aria-pressed",active?"true":"false")})}window.__tfhSyncLangSwitchers=sync;function onClick(e){var btn=e.target.closest(".lang-btn[data-lang]");if(btn){var lang=btn.getAttribute("data-lang");if(lang!==(window.currentLanguage||"fr"))if(typeof window.setLanguage=="function")window.setLanguage(lang);else{try{localStorage.setItem("openfront_lang",lang)}catch{}window.location.reload()}}}function injectSidebarSwitcher(){if(!document.querySelector(".lang-switcher")){var sidebar=document.querySelector("aside.sidebar");if(sidebar){var anchor=sidebar.querySelector(".theme-toggle"),box=document.createElement("div");box.className="lang-switcher",box.setAttribute("role","group"),box.setAttribute("aria-label","Langue / Language");var label=document.createElement("span");label.className="lang-switcher-label",label.setAttribute("data-i18n","lang.label"),label.textContent=window.t?window.t("lang.label"):"Langue",box.appendChild(label);var btns=document.createElement("div");btns.className="lang-switcher-btns",btns.innerHTML=buttonsHtml(),box.appendChild(btns),anchor&&anchor.parentNode===sidebar?anchor.insertAdjacentElement("afterend",box):sidebar.appendChild(box)}}}function hydrateChoiceZones(){document.querySelectorAll("[data-lang-choice]").forEach(function(zone){zone.querySelector(".lang-btn")||(zone.innerHTML=buttonsHtml())})}function init(){injectSidebarSwitcher(),hydrateChoiceZones(),sync(window.currentLanguage||"fr")}document.addEventListener("click",onClick),document.readyState==="loading"?document.addEventListener("DOMContentLoaded",init):init()})();
